function registerDoctorCommand(program3) {
  program3.command("doctor").description("Check environment and configuration").action(async () => {
    let ok2 = true;
    const nodeVersion = process.version;
    const major = parseInt(nodeVersion.slice(1).split(".")[0], 10);
    if (major >= 22) {
      console.log(`  Node: ${nodeVersion}`);
    } else {
      console.error(`  Node: ${nodeVersion} (need >=22)`);
      ok2 = false;
    }
    try {
      execSync("pnpm --version", { stdio: "pipe" });
      console.log("  pnpm: available");
    } catch {
      console.error("  pnpm: not found");
      ok2 = false;
    }
    const cwd = process.cwd();
    console.log(`  CWD:  ${cwd}`);
    const manifestPath = join4(cwd, "skills-release.json");
    if (existsSync(manifestPath) && existsSync(join4(cwd, "skills"))) {
      try {
        const manifest = JSON.parse(readFileSync(manifestPath, "utf-8"));
        const stale = [];
        for (const [name, sha] of Object.entries(manifest)) {
          const p3 = join4(cwd, "skills", name, "SKILL.md");
          if (!existsSync(p3)) continue;
          if (createHash("sha256").update(readFileSync(p3)).digest("hex") !== sha) {
            stale.push(name);
          }
        }
        if (stale.length > 0) {
          console.warn(`  Skills: ${stale.length} stale vs skills-release.json (update recommended)`);
        } else {
          console.log(`  Skills: ${Object.keys(manifest).length} up-to-date`);
        }
      } catch {
        console.log("  Skills: manifest unreadable (skipped staleness check)");
      }
    }
    const hasRoot = existsSync(join4(cwd, "aix.json"));
    const hasDot = existsSync(join4(cwd, ".aix", "static", "config.json"));
    if (hasRoot || hasDot) {
      const found = hasRoot ? "aix.json" : ".aix/static/config.json";
      console.log(`  Config: ${found}`);
    } else {
      console.log("  Config: not found (optional \u2014 create aix.json to customize)");
    }
    const skillsDir = join4(cwd, "skills");
    if (existsSync(skillsDir)) {
      try {
        execSync("ls", { cwd: skillsDir, stdio: "pipe" });
        console.log(`  Dry-run: skills/ readable (${skillsDir})`);
      } catch {
        console.error("  Dry-run: skills/ exists but not readable");
        ok2 = false;
      }
    } else {
      console.log("  Dry-run: skills/ not found (skipping compile check)");
    }
    if (ok2) {
      console.log("System OK");
    } else {
      console.error("Issues found");
      process.exit(1);
    }
  });
}

